total = 0
written = 0
for cid in IDS:
    assert cid in P, cid
    obj = {"case_id": cid, "prediction_text": P[cid]["prediction_text"],
           "basis": P[cid]["basis"], "confidence": P[cid]["confidence"],
           "trigger": P[cid]["trigger"]}
    path = os.path.join(OUT, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    # 逐件自验
    with open(path, encoding="utf-8") as f:
        back = json.load(f)
    assert back["case_id"] == cid
    for k in ("case_id","prediction_text","basis","confidence","trigger"):
        assert k in back, (cid, k)
    assert 0 <= back["confidence"] <= 1
    for k in ("changed_main","reserve_used","disputed","reason"):
        assert k in back["trigger"], (cid, k)
    total += os.path.getsize(path)
    written += 1
assert written == 20, written
